import requests

URL_BASE = "https://economia.awesomeapi.com.br/json"


def _buscar(caminho):
    """Faz o GET e devolve o JSON, ou None se algo falhar."""
    try:
        resposta = requests.get(f"{URL_BASE}/{caminho}", timeout=10)
    except requests.RequestException:
        return None
    if resposta.status_code != 200:
        return None
    return resposta.json()


def obter_cotacao(origem, destino):
    """Rota /cotacao: preço de compra (bid) do par, ou 0.0."""
    par = f"{origem}-{destino}".upper()
    dados = _buscar(f"last/{par}")
    if not dados:
        return 0.0
    return float(dados[par.replace("-", "")]["bid"])


def converter(valor, origem, destino):
    """Rota /converter: devolve (resultado, taxa) ou (None, 0.0)."""
    taxa = obter_cotacao(origem, destino)
    if taxa > 0:
        return valor * taxa, taxa
    return None, 0.0


def obter_historico(origem, destino, dias=5):
    """Rota /historico: lista de cotações diárias, ou lista vazia."""
    par = f"{origem}-{destino}".upper()
    return _buscar(f"daily/{par}/{dias}") or []


