import streamlit as st
import pandas as pd
from api_financeira import converter, obter_cotacao, obter_historico

st.set_page_config(page_title="Monitor de Cotações", page_icon="💰")
st.title("💰 Monitor de Cotações V1")

MOEDAS = ["USD", "EUR", "GBP", "JPY", "CAD", "BRL"]


@st.cache_data(ttl=60)
def cotacao_cache(origem, destino):
    return obter_cotacao(origem, destino)


@st.cache_data(ttl=60)
def converter_cache(valor, origem, destino):
    return converter(valor, origem, destino)


@st.cache_data(ttl=600)
def historico_cache(origem, destino, dias):
    return obter_historico(origem, destino, dias)


with st.sidebar:
    st.header("Moedas")
    origem = st.selectbox("Origem", MOEDAS, index=0)
    destino = st.selectbox("Destino", MOEDAS, index=5)

aba_cot, aba_conv, aba_hist = st.tabs(["Cotação", "Converter", "Histórico"])

with aba_cot:
    if st.button("Buscar cotação"):
        taxa = cotacao_cache(origem, destino)
        if taxa > 0:
            st.metric(f"1 {origem} em {destino}", f"{taxa:.4f}")
        else:
            st.error("Par indisponível ou falha na API.")

with aba_conv:
    valor = st.number_input("Valor", min_value=0.01, value=100.0, step=10.0)
    if st.button("Converter"):
        resultado, taxa = converter_cache(valor, origem, destino)
        if resultado is not None:
            st.metric(f"{valor:.2f} {origem} em {destino}", f"{resultado:.2f} {destino}")
            with st.expander("Ver taxa utilizada"):
                st.write(f"1 {origem} = {taxa:.6f} {destino}")
        else:
            st.error("Não foi possível converter. Verifique as moedas.")

with aba_hist:
    dias = st.slider("Número de dias", 1, 30, 7)
    if st.button("Ver histórico"):
        lista = historico_cache(origem, destino, dias)
        if lista:
            df = pd.DataFrame(lista)
            df["data"] = pd.to_datetime(df["timestamp"].astype(int), unit="s")
            df["bid"] = df["bid"].astype(float)
            st.line_chart(df.set_index("data")["bid"])
            st.dataframe(df[["data", "bid", "high", "low", "pctChange"]], hide_index=True)
        else:
            st.info("Nenhum dado histórico encontrado.")

